from sqisign import SQIsign


def test_single_kat():
    # From KATS
    mlen = 33
    msg = "D81C4D8D734FCBFBEADE3D3F8A039FAA2A2C9957E835AD55B22E75BF57BB556AC8"
    pk = "C32377D6F6D70729884A7F6877EF4791E35D21F751A3E96DE23F9A7A3C01BCD8A5F146DC19E4E2AC63007457F97D8A40EE84AEE7564CA9A7FBE6200FD3E5E55901BFC60EB25C50D39F5C91C96510556BAA22028DF76360841721A601D65E8D0F06"
    sm = ""

    sqisign = SQIsign(security_level=3)
    message = bytes.fromhex(msg)
    assert len(message) == mlen
    sm = bytes.fromhex(sm)
    signature = sm[:-mlen]
    public_key = bytes.fromhex(pk)

    check = sqisign.verify(message, signature, public_key)

    assert check


if __name__ == "__main__":
    test_single_kat()
